import React from "react";

export default function About() {
  return (
    <div className="about-page">

      <div className="about-wrapper">

        {/* LEFT SIDE */}
        <div className="about-left">

          {/* ABOUT ME */}
          <div className="about-top">
            <h1>
              About <span>Me</span>
            </h1>

            <p>
              I am an Information Technology student who enjoys building 
              practical and meaningful digital solutions. I am driven by 
              curiosity and a desire to continuously improve my technical 
              abilities through real-world applications.
            </p>

            <p>
              I believe in learning by doing — exploring new technologies, 
              experimenting with ideas, and refining my approach to problem-solving 
              through consistent practice and development.
            </p>
          </div>

          {/* WHAT I DO */}
          <div className="what-i-do">
            <h3>🚀 What I Do</h3>
            <p>
              I work on developing structured and responsive web applications, 
              focusing on writing clean code and creating smooth user experiences. 
              My approach involves understanding the problem clearly, designing 
              efficient solutions, and implementing them using modern development 
              tools and frameworks.
            </p>

            <p>
              I also explore backend concepts and data handling to ensure that 
              applications are not only visually appealing but also functionally 
              strong and scalable.
            </p>
          </div>

        </div>

        {/* RIGHT SIDE */}
        <div className="about-right">

          {/* EDUCATION */}
          <div className="card">
            <div className="card-header">
              <h3>🎓 Education</h3>
              <span className="year">2023–2027</span>
            </div>

            <p><strong>B.Tech – Information Technology</strong></p>
            <p className="college">Panimalar Engineering College</p>

            <p>
              Through my academic journey, I am developing a strong foundation 
              in core areas such as programming, database management, and system 
              design. Alongside theoretical learning, I actively apply concepts 
              through projects to gain practical exposure and deeper understanding.
            </p>
          </div>

          {/* INTERESTS */}
          <div className="card">
            <h3>💡 Interests</h3>
            <ul>
              <li>Building full stack web applications</li>
              <li>Working with data and analytics</li>
              <li>Designing clean and intuitive user interfaces</li>
              <li>Exploring new technologies and tools</li>
            </ul>
          </div>

        </div>

      </div>

      {/* STATS */}
      <div className="stats">
        <div className="stat-box">
          <h3>5+</h3>
          <p>Projects</p>
        </div>
        <div className="stat-box">
          <h3>10+</h3>
          <p>Technologies</p>
        </div>
        <div className="stat-box">
          <h3>2+</h3>
          <p>Domains</p>
        </div>
      </div>

      <style>{`

        .about-page {
          min-height: 100vh;
          padding: 60px 10%;
          font-family: "Poppins", sans-serif;
          background: #0f172a;
          color: white;
        }

        .about-wrapper {
          display: grid;
          grid-template-columns: 1.2fr 1fr;
          gap: 50px;
          align-items: start;
        }

        /* ALIGN ABOUT WITH EDUCATION */
        .about-top {
          margin-bottom: 25px;
        }

        .about-left h1 {
          font-size: 42px;
          margin-bottom: 10px;
        }

        .about-left span {
          color: #38BDF8;
        }

        .about-left p {
          color: #cbd5e1;
          line-height: 1.8;
          margin-bottom: 10px;
        }

        /* WHAT I DO */
        .what-i-do {
          padding: 18px;
          border-radius: 10px;
          background: rgba(255,255,255,0.05);
          border-left: 4px solid #38BDF8;
        }

        .what-i-do h3 {
          margin-bottom: 8px;
          color: #38BDF8;
        }

        /* RIGHT SIDE */
        .about-right {
          display: flex;
          flex-direction: column;
          gap: 20px;
        }

        .card {
          background: rgba(255,255,255,0.05);
          padding: 22px;
          border-radius: 14px;
          border: 1px solid rgba(56,189,248,0.2);
          transition: 0.3s;
        }

        .card:hover {
          transform: translateY(-5px);
          box-shadow: 0 0 20px rgba(56,189,248,0.4);
        }

        .card h3 {
          margin-bottom: 8px;
          color: #38BDF8;
        }

        .card p, li {
          color: #cbd5e1;
          font-size: 15px;
          line-height: 1.6;
        }

        /* HEADER */
        .card-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          margin-bottom: 6px;
        }

        .year {
          background: rgba(56,189,248,0.2);
          color: #38BDF8;
          padding: 2px 10px;
          border-radius: 10px;
          font-size: 11px;
          font-weight: 600;
        }

        .college {
          color: #7dd3fc;
          font-weight: 500;
        }

        ul {
          padding-left: 18px;
        }

        li {
          margin-bottom: 6px;
        }

        /* STATS */
        .stats {
          display: flex;
          gap: 20px;
          margin-top: 40px;
        }

        .stat-box {
          flex: 1;
          text-align: center;
          padding: 15px;
          border-radius: 10px;
          background: rgba(255,255,255,0.05);
        }

        .stat-box h3 {
          color: #38BDF8;
        }

        /* MOBILE */
        @media (max-width: 900px) {
          .about-wrapper {
            grid-template-columns: 1fr;
          }

          .stats {
            flex-direction: column;
          }
        }

      `}</style>

    </div>
  );
}
